/*
 * The grid draws only; this decides what it shows. Filters: All, then each kind she has at least one
 * of, in the option set's order, with how many. Choosing one shows only that kind; if its last one is
 * deleted, All again. One creation is open at a time, drawn above the grid. Row ids are prefixed
 * (a For Each row is a Model named by its id for the whole app); the prefix is taken off here.
 * A kind row's own id is ck-<kind>; the value a Creation holds is its `kind`.
 */
let filter = 'all';
let openId = '';

Script.Inputs = { items: 'array', kinds: 'array', mode: 'string', chipId: 'string', cardId: 'string' };
Script.Outputs = {
  cards: 'array', chips: 'array', hasItems: 'boolean', showGrid: 'boolean', none: 'boolean', noneOfKind: 'boolean',
  isOpen: 'boolean', vTitle: 'string', vKindKey: 'string', vKindBg: 'string', vKindFg: 'string',
  vMadeWith: 'string', vHasMadeWith: 'boolean', vStepTitle: 'string', vHasStep: 'boolean',
  vDescription: 'string', vHasDescription: 'boolean', vIsFile: 'boolean', vIsLink: 'boolean', vIsText: 'boolean',
  vFiles: 'array', vUrl: 'string', vText: 'string', opened: 'signal', editItem: '*', edit: 'signal'
};

const get = (m, k) => (m && typeof m.get === 'function' ? m.get(k) : m && m[k]);
const CARD = 'creation-card-';
const CHIP = 'creation-filter-';
const items = () => Array.from(Script.Inputs.items || []);
const kindOf = (id) => (Script.Inputs.kinds || []).find((k) => get(k, 'kind') === id) || null;

function shape() {
  const all = items();
  const own = Script.Inputs.mode !== 'coach';
  const counts = {};
  all.forEach((c) => { counts[c.kind] = (counts[c.kind] || 0) + 1; });
  if (filter !== 'all' && !counts[filter]) filter = 'all';
  const shown = filter === 'all' ? all : all.filter((c) => c.kind === filter);
  const badge = (c) => {
    const k = kindOf(c.kind) || kindOf('other');
    return { kindKey: get(k, 'labelKey') || '', kindBg: get(k, 'bg') || '', kindFg: get(k, 'fg') || '' };
  };
  Script.Outputs.cards = shown.map((c) => Object.assign({
    id: CARD + c.id,
    title: c.title,
    madeWith: c.madeWith || '',
    hasMadeWith: !!c.madeWith,
    stepTitle: c.stepTitle || '',
    hasStep: !!c.stepTitle,
    usedInClass: c.usedInClass === true,
    canEdit: own
  }, badge(c)));
  const chips = [{ id: CHIP + 'all', kind: 'all', labelKey: 'creations.filterAll', n: String(all.length), selected: filter === 'all' }];
  (Script.Inputs.kinds || []).forEach((k) => {
    const id = get(k, 'kind');
    if (counts[id]) chips.push({ id: CHIP + id, kind: id, labelKey: get(k, 'filterKey'), n: String(counts[id]), selected: filter === id });
  });
  Script.Outputs.chips = chips;
  Script.Outputs.hasItems = all.length > 0;
  Script.Outputs.showGrid = shown.length > 0;
  Script.Outputs.none = all.length === 0;
  Script.Outputs.noneOfKind = all.length > 0 && shown.length === 0;

  const o = all.find((c) => c.id === openId) || null;
  if (!o) openId = '';
  Script.Outputs.isOpen = !!o;
  const b = o ? badge(o) : {};
  Script.Outputs.vTitle = o ? o.title : '';
  Script.Outputs.vKindKey = b.kindKey || '';
  Script.Outputs.vKindBg = b.kindBg || '';
  Script.Outputs.vKindFg = b.kindFg || '';
  Script.Outputs.vMadeWith = o ? o.madeWith || '' : '';
  Script.Outputs.vHasMadeWith = !!(o && o.madeWith);
  Script.Outputs.vStepTitle = o ? o.stepTitle || '' : '';
  Script.Outputs.vHasStep = !!(o && o.stepTitle);
  Script.Outputs.vDescription = o ? o.description || '' : '';
  Script.Outputs.vHasDescription = !!(o && o.description);
  Script.Outputs.vIsFile = !!o && o.form === 'file';
  Script.Outputs.vIsLink = !!o && o.form === 'link';
  Script.Outputs.vIsText = !!o && o.form === 'text';
  Script.Outputs.vFiles = o && o.form === 'file'
    ? (o.files || []).map((f, i) => ({ id: 'creation-file-' + o.id + '-' + i, file: f.file, fileName: f.fileName, mode: own ? 'own' : 'coach' }))
    : [];
  Script.Outputs.vUrl = o ? o.url || '' : '';
  Script.Outputs.vText = o ? o.text || '' : '';
}

Script.OnInit = function () { shape(); };
Script.Setters.items = function () { shape(); };
Script.Setters.kinds = function () { shape(); };
Script.Setters.mode = function () { shape(); };
Script.Signals.pickFilter = function () {
  filter = String(Script.Inputs.chipId || '').replace(CHIP, '') || 'all';
  shape();
};
Script.Signals.open = function () {
  openId = String(Script.Inputs.cardId || '').replace(CARD, '');
  shape();
  Script.Outputs.opened();
};
Script.Signals.close = function () {
  openId = '';
  shape();
};
Script.Signals.edit = function () {
  const id = String(Script.Inputs.cardId || '').replace(CARD, '');
  const c = items().find((x) => x.id === id);
  if (!c) return;
  Script.Outputs.editItem = c;
  Script.Outputs.edit();
};
